css:
:scope { width: min(100%, 1353px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 10; grid-row: 1 / span 85; aspect-ratio: 544 / 680; }
.gx__i2 { grid-column: 11 / span 13; grid-row: 6 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i3 { grid-column: 11 / span 13; grid-row: 10 / span 17; font-family: var(--os-font-heading); font-size: 72.6px; font-weight: 700; line-height: 0.95; letter-spacing: -0.022em; color: var(--os-color-heading); }
.gx__i4 { grid-column: 11 / span 13; grid-row: 31 / span 5; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.55; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i5 { grid-column: 11 / span 13; grid-row: 37 / span 34; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.55; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i6 { grid-column: 11 / span 13; grid-row: 72 / span 29; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.55; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i7 { grid-column: 19 / span 2; grid-row: 108 / span 2; font-family: var(--os-font-label); font-size: 12.8px; font-weight: 700; line-height: 1.33; letter-spacing: 0.18em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i8 { grid-column: 21 / span 3; grid-row: 108 / span 2; font-family: var(--os-font-label); font-size: 12.8px; font-weight: 700; line-height: 1.33; letter-spacing: 0.18em; text-transform: uppercase; color: var(--os-color-heading); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i2 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 58px; }
  .gx__i4 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i5 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i6 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i7 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i8 { font-family: var(--os-font-label); font-size: 14px; }
}
